import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4
__global__ void __launch_bounds__(256, 6) triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    int bx = blockIdx.x; // tile index along columns (N dimension)
    int by = blockIdx.y; // tile index along rows (M dimension)
    int rowBase = by * BM;
    int colBase = bx * BN;
    int tx = threadIdx.x; // 0..15 (BN/TN)
    int ty = threadIdx.y; // 0..15 (BM/TM)
    int tid = ty * blockDim.x + tx;
    int numThreads = blockDim.x * blockDim.y;
    // Entire block lies strictly below the diagonal -> result is all zeros.
    // Write zeros directly here so we avoid a separate zero-initialization
    // kernel launch (torch::zeros) for the entire output tensor.
    if (rowBase > colBase + BN - 1) {
        for (int idx = tid; idx < BM * BN; idx += numThreads) {
            int r = idx / BN;
            int c = idx % BN;
            int globalRow = rowBase + r;
            int globalCol = colBase + c;
            if (globalRow < N && globalCol < N) {
                C[globalRow * N + globalCol] = 0.0f;
            }
        }
        return;
    }
    __shared__ float As[2][BM][BK];
    __shared__ float Bs[2][BK][BN];
    float accum[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            accum[i][j] = 0.0f;
        }
    }
    // Only need to accumulate over k tiles overlapping [rowBase, colBase+BN-1] because
    // A is upper triangular (A[i][k] = 0 for k < i) and
    // B is upper triangular (B[k][j] = 0 for k > j).
    int kStart = (rowBase / BK) * BK;
    int kEndExclusive = colBase + BN;
    int kLimit = kEndExclusive < N ? kEndExclusive : N;
    int numTiles = (kLimit > kStart) ? ((kLimit - kStart + BK - 1) / BK) : 0;
    const int totalAsVec = (BM * BK) / 4;
    const int totalBsVec = (BK * BN) / 4;
    if (numTiles > 0) {
        int k0 = kStart;
        for (int idx = tid; idx < totalAsVec; idx += numThreads) {
            int elemIdx = idx * 4;
            int r = elemIdx / BK;
            int c = elemIdx % BK;
            int globalRow = rowBase + r;
            int globalCol = k0 + c;
            float4 val;
            if (globalRow < N && globalCol + 3 < N) {
                val = *reinterpret_cast<const float4*>(&A[globalRow * N + globalCol]);
            } else {
                val.x = (globalRow < N && globalCol < N) ? A[globalRow * N + globalCol] : 0.0f;
                val.y = (globalRow < N && globalCol + 1 < N) ? A[globalRow * N + globalCol + 1] : 0.0f;
                val.z = (globalRow < N && globalCol + 2 < N) ? A[globalRow * N + globalCol + 2] : 0.0f;
                val.w = (globalRow < N && globalCol + 3 < N) ? A[globalRow * N + globalCol + 3] : 0.0f;
            }
            *reinterpret_cast<float4*>(&As[0][r][c]) = val;
        }
        for (int idx = tid; idx < totalBsVec; idx += numThreads) {
            int elemIdx = idx * 4;
            int r = elemIdx / BN;
            int c = elemIdx % BN;
            int globalRow = k0 + r;
            int globalCol = colBase + c;
            float4 val;
            if (globalRow < N && globalCol + 3 < N) {
                val = *reinterpret_cast<const float4*>(&B[globalRow * N + globalCol]);
            } else {
                val.x = (globalRow < N && globalCol < N) ? B[globalRow * N + globalCol] : 0.0f;
                val.y = (globalRow < N && globalCol + 1 < N) ? B[globalRow * N + globalCol + 1] : 0.0f;
                val.z = (globalRow < N && globalCol + 2 < N) ? B[globalRow * N + globalCol + 2] : 0.0f;
                val.w = (globalRow < N && globalCol + 3 < N) ? B[globalRow * N + globalCol + 3] : 0.0f;
            }
            *reinterpret_cast<float4*>(&Bs[0][r][c]) = val;
        }
        __syncthreads();
    }
    int curBuf = 0;
    for (int t = 0; t < numTiles; ++t) {
        int nextBuf = 1 - curBuf;
        if (t + 1 < numTiles) {
            int k0 = kStart + (t + 1) * BK;
            for (int idx = tid; idx < totalAsVec; idx += numThreads) {
                int elemIdx = idx * 4;
                int r = elemIdx / BK;
                int c = elemIdx % BK;
                int globalRow = rowBase + r;
                int globalCol = k0 + c;
                float4 val;
                if (globalRow < N && globalCol + 3 < N) {
                    val = *reinterpret_cast<const float4*>(&A[globalRow * N + globalCol]);
                } else {
                    val.x = (globalRow < N && globalCol < N) ? A[globalRow * N + globalCol] : 0.0f;
                    val.y = (globalRow < N && globalCol + 1 < N) ? A[globalRow * N + globalCol + 1] : 0.0f;
                    val.z = (globalRow < N && globalCol + 2 < N) ? A[globalRow * N + globalCol + 2] : 0.0f;
                    val.w = (globalRow < N && globalCol + 3 < N) ? A[globalRow * N + globalCol + 3] : 0.0f;
                }
                *reinterpret_cast<float4*>(&As[nextBuf][r][c]) = val;
            }
            for (int idx = tid; idx < totalBsVec; idx += numThreads) {
                int elemIdx = idx * 4;
                int r = elemIdx / BN;
                int c = elemIdx % BN;
                int globalRow = k0 + r;
                int globalCol = colBase + c;
                float4 val;
                if (globalRow < N && globalCol + 3 < N) {
                    val = *reinterpret_cast<const float4*>(&B[globalRow * N + globalCol]);
                } else {
                    val.x = (globalRow < N && globalCol < N) ? B[globalRow * N + globalCol] : 0.0f;
                    val.y = (globalRow < N && globalCol + 1 < N) ? B[globalRow * N + globalCol + 1] : 0.0f;
                    val.z = (globalRow < N && globalCol + 2 < N) ? B[globalRow * N + globalCol + 2] : 0.0f;
                    val.w = (globalRow < N && globalCol + 3 < N) ? B[globalRow * N + globalCol + 3] : 0.0f;
                }
                *reinterpret_cast<float4*>(&Bs[nextBuf][r][c]) = val;
            }
        }
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float aReg[TM];
            float bReg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                aReg[i] = As[curBuf][ty * TM + i][kk];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                bReg[j] = Bs[curBuf][kk][tx * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    accum[i][j] += aReg[i] * bReg[j];
                }
            }
        }
        if (t + 1 < numTiles) {
            __syncthreads();
        }
        curBuf = nextBuf;
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int row = rowBase + ty * TM + i;
        if (row >= N) continue;
        int colBaseTx = colBase + tx * TN;
        if (colBaseTx + TN - 1 < N) {
            float4 val;
            val.x = (row <= colBaseTx + 0) ? accum[i][0] : 0.0f;
            val.y = (row <= colBaseTx + 1) ? accum[i][1] : 0.0f;
            val.z = (row <= colBaseTx + 2) ? accum[i][2] : 0.0f;
            val.w = (row <= colBaseTx + 3) ? accum[i][3] : 0.0f;
            *reinterpret_cast<float4*>(&C[row * N + colBaseTx]) = val;
        } else {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int col = colBaseTx + j;
                if (col >= N) continue;
                C[row * N + col] = (row <= col) ? accum[i][j] : 0.0f;
            }
        }
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);

    auto C = torch::empty({N, N}, A.options());

    dim3 block(BN / TN, BM / TM);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);

    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

triu_matmul_cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul = load_inline(
    name="triu_matmul",
    cpp_sources=triu_matmul_cpp_source,
    cuda_sources=triu_matmul_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom fused CUDA kernel that exploits the
    triangular structure of A and B to reduce redundant computation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.triu_matmul = triu_matmul

    def forward(self, A, B):
        return self.triu_matmul.triu_matmul_cuda(A, B)


N = 4096
def get_inputs():
    A = torch.triu(torch.rand(N, N)).cuda()
    B = torch.triu(torch.rand(N, N)).cuda()
    return [A, B]

def get_init_inputs():
    return []

